INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19501, 'Ezekiel 8:12', 'Ezekiel', 8, 12, '&nbsp;نو بيا مالِک خُدائ ما ته وفرمائيل چې، ”اے بنى آدمه، تا هغه څۀ وليدل کوم چې د اِسرائيلو مشرانو په تيارۀ کوټه کښې هر يو د خپل معبود د زيارت دپاره کول؟ هغوئ دا وائى چې، مالِک خُدائ مونږ نۀ وينى، مالِک خُدائ دا مُلک پرېښے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19502, 'Ezekiel 8:13', 'Ezekiel', 8, 13, '&nbsp;هغۀ بيا وفرمائيل چې، ”تۀ به هغوئ د دې نه هم په ډېرو خرابو حرامو کارونو کولو باندې وګورې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19503, 'Ezekiel 8:14', 'Ezekiel', 8, 14, '&nbsp;نو بيا زۀ هغۀ د مالِک خُدائ کور ته د ننوتلو د شمال خوا دروازې ته راوستلم، ما هلته ښځې وليدلې چې ناستې وې او د تموز معبود ژړا او ماتم يې کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19504, 'Ezekiel 8:15', 'Ezekiel', 8, 15, '&nbsp;هغۀ ما ته وفرمائيل چې، ”اے بنى آدمه، تۀ دا وينې؟ نو تۀ به نور داسې حرام کارونه وګورې کوم چې به د دې نه هم ډېر پليت او خراب وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19505, 'Ezekiel 8:16', 'Ezekiel', 8, 16, '&nbsp;هغۀ بيا زۀ د مالِک خُدائ د کور دننه دربار ته راوستلم، او هلته د مالِک خُدائ د کور د داخلېدلو په لار او د برنډې او د قربان‌ګاه په مينځ کښې پينځويشت کسان وُو. چې شا يې د مالِک خُدائ کور ته وه او د هغوئ مخ د نمرخاتۀ خوا ته وو، هغوئ د مشرق خوا ته نمر ته سجده کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19506, 'Ezekiel 8:17', 'Ezekiel', 8, 17, '&nbsp;هغۀ ما ته وفرمائيل چې، ”اے بنى آدمه تا دا وليدل؟ ولې دا د يهوداه خلقو ته مناسبه ده چې هغوئ دې داسې پليت او حرام کارونه دلته وکړى؟ دا ضرورى ده چې دوئ دُنيا هم د شرارت نه ډکه کړى او په مسلسله توګه زما قهر و غضب راوپاروى؟ هغوئ ته وګوره چې خپله پوزه چوڼى او ما ته سپک نظر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19507, 'Ezekiel 8:18', 'Ezekiel', 8, 18, '&nbsp;نو په دې وجه زۀ به په هغوئ باندې خپل غضب نازل کړم، نۀ به هغوئ زما نه بچ شى او نۀ به زۀ په هغوئ رحم وکړم. کۀ څۀ هم چې هغوئ زما په غوږ کښې چغې ووهى زۀ به هغوئ ته غوږ نۀ نيسم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19508, 'Ezekiel 9:1', 'Ezekiel', 9, 1, '&nbsp;نو بيا مالِک خُدائ په اوچت آواز سره وفرمائيل، ”هغه کسان راولئ کوم چې د ښار د سزا ورکولو دپاره مقرر شوى دى نو هغوئ ته ووايه چې هر يو د خپلو تباه کوونکو وسلو په لاس راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19509, 'Ezekiel 9:2', 'Ezekiel', 9, 2, '&nbsp;نو بيا شپږ کسان د شمال بره طرف دروازې نه راښکاره شُو، د هر يو په لاس کښې وژونکې وسله وه. د هغوئ سره يو کس وو چې د کتان جامې يې وې، چا سره چې د خط و کتابت سامان په څنګ کښې وو. هغوئ ټول د مالِک خُدائ د کور دربار ته لاړل او د زېړو د قربان‌ګاه په خوا کښې ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19510, 'Ezekiel 9:3', 'Ezekiel', 9, 3, '&nbsp;بيا د بنى اِسرائيلو د خُدائ پاک جلال د وزرو والا مخلوق دپاسه راوچت شو، په کوم ځائ کښې چې هغه وو، نو بيا د خُدائ د کور درشل ته لاړو. نو بيا مالِک خُدائ هغه کس ته آواز وکړو چې د کتان جامې يې اچولې وې د چا سره چې د خط و کتابت سامان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19511, 'Ezekiel 9:4', 'Ezekiel', 9, 4, '&nbsp;او هغۀ ته يې وفرمائيل چې، ”د يروشلم په ټول ښار کښې وګرځه او د هر هغه چا په تندى باندې نښه ولګوه څوک چې وير او ماتم کوى په هغه ټولو حرامو کارونو باندې چې په دې کښې وشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19512, 'Ezekiel 9:5', 'Ezekiel', 9, 5, '&nbsp;نو چې ما غوږ ونيولو، هغۀ هغه نورو ته وفرمائيل، ”په ښار کښې هغۀ پسې ځئ او خلق مړۀ کړئ، په چا زړۀ مۀ سوزوئ او مۀ په چا رحم کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19513, 'Ezekiel 9:6', 'Ezekiel', 9, 6, '&nbsp;بوډاګان، ځوانان، پېغلې، ښځې، او ماشومان، حلال کړئ، خو هغوئ ته لاس مۀ وروړئ د چا په تندى باندې چې نښه لګېدلې وى. زما د مقدس ځائ نه شروع وکړئ.“ نو بيا هغوئ دا کار د هغه مشرانو نه شروع کړو چې د خُدائ د کور په مخکښې ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19514, 'Ezekiel 9:7', 'Ezekiel', 9, 7, '&nbsp;نو بيا هغۀ هغوئ ته وفرمائيل، ”زما کور پليت او زما دربار د مړو د لاشونو نه ډک کړئ. ځئ لاړ شئ.“ نو هغوئ بهر لاړل او په ټول ښار کښې يې په مرګ شروع وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19515, 'Ezekiel 9:8', 'Ezekiel', 9, 8, '&nbsp;نو کله چې هغوئ خلق وژل او زۀ يواځې پاتې شوم، نو زۀ پړمخې پرېوتم او چغې مې کړې، ”اے مالِک قادر مطلق خُدايه، په يروشلم باندې د خپل غضب په نازلېدو سره ولې تۀ د بنى اِسرائيلو دا بچ پاتې شوى خلق به هم تباه کوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19516, 'Ezekiel 9:9', 'Ezekiel', 9, 9, '&nbsp;نو بيا هغۀ ما ته وفرمائيل چې، ”د اِسرائيل او د يهوداه د خلقو ګناهونه ډېر بې‌حده غټ دى، مُلک د قتل و غارت نه ډک دے او ښار د بې‌اِنصافۍ نه ډک دے. هغوئ وائى، مالِک خُدائ دا مُلک پرېښے دے، مالِک خُدائ دا نۀ وينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19517, 'Ezekiel 9:10', 'Ezekiel', 9, 10, '&nbsp;نو زۀ به هغوئ ته د رحم په سترګه نۀ ګورم او نۀ به هغوئ بچ کړم، خو زۀ به هم د دوئ په سرونو هغه څۀ راولم څۀ چې هغوئ کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19518, 'Ezekiel 9:11', 'Ezekiel', 9, 11, '&nbsp;بيا هغه سړى چې د کتان جامې يې اچولې وې او د خط و کتابت سامان ورسره وو هغۀ دا خبر راوړو، او وې وئيل، ”ما هغه څۀ وکړل څنګه چې تا حکم کړے وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19519, 'Ezekiel 10:1', 'Ezekiel', 10, 1, '&nbsp;کله چې ما بره وکتل، د وزرو والا د مخلوق د سر دپاسه په آسمان کښې ما نيلم کاڼے وليدو چې لکه د تخت په شان ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19520, 'Ezekiel 10:2', 'Ezekiel', 10, 2, '&nbsp;مالِک خُدائ هغه سړى ته چا چې د کتان جامې اچولې وې وفرمائيل، ”د وزرو والا مخلوق د پايو د لاندې په مينځ کښې تېر شه. خپل لاسونه د سکروټو نه ډک کړه او په ښار يې وشينده.“ او چې ما وليدل هغه هم هغه شان دننه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19521, 'Ezekiel 10:3', 'Ezekiel', 10, 3, '&nbsp;اوس د وزرو والا مخلوق د خُدائ د کور د جنوبى دروازې سره ولاړ وو کله چې هغه سړے دننه لاړو، نو وريځې دننه دربار ډک کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19522, 'Ezekiel 10:4', 'Ezekiel', 10, 4, '&nbsp;نو بيا د مالِک خُدائ جلال د وزرو والا مخلوق دپاسه راوچت شو او د خُدائ د کور درشل ته لاړو. وريځو د خُدائ کور ډک کړو، او د هغۀ دربار د مالِک خُدائ د جلال د شغلو نه ډک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19523, 'Ezekiel 10:5', 'Ezekiel', 10, 5, '&nbsp;د وزرو والا مخلوق د وزرو آواز د لرې پورې اورېدلے شو تر بهرنى درباره پورې، هغه داسې ښکارېدو لکه د قادر خُدائ د آواز په شان کله چې هغه خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19524, 'Ezekiel 10:6', 'Ezekiel', 10, 6, '&nbsp;کله چې مالِک خُدائ هغه سړى له حُکم وکړو چا چې د کتان جامې اغوستې وې، ”د وزرو والا مخلوق د لاندې لاړ شه او د پايو د مينځ نه اور راواخله،“ هغه سړے لاندې ورغلو او د يوې پايې په خوا کښې ودرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19525, 'Ezekiel 10:7', 'Ezekiel', 10, 7, '&nbsp;نو بيا د وزرو والا په مخلوق کښې يو خپل لاس هغه اور ته وراوږد کړو کوم چې د هغوئ په مينځ کښې بلېدلو. هغۀ د هغه اور نه لږ راوچت کړو او د هغه سړى په لاس کښې يې واچولو چې د کتان جامې يې اغوستې وې، نو بيا هغه سړى اور واخستو او بهر لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19526, 'Ezekiel 10:8', 'Ezekiel', 10, 8, '&nbsp;نو ما بيا وکتل چې هر يو د څلورو وزرو والا مخلوق د وزرونو لاندې يو څيز ليدل کېدو چې د انسان د لاس په شان ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19527, 'Ezekiel 10:9', 'Ezekiel', 10, 9, '&nbsp;ما وکتل چې، د هر يو څلور وزرو والا مخلوق سره په خوا کښې يوه پايه وه، او هغه پايې لکه د ايکوامرين کاڼو په شان ځلېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19528, 'Ezekiel 10:10', 'Ezekiel', 10, 10, '&nbsp;څلور واړه پايې يو شان ښکارېدې او يو رنګ جوړې شوې وې، او په هره يوه پايه کښې يوه بله پايه چورلېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19529, 'Ezekiel 10:11', 'Ezekiel', 10, 11, '&nbsp;د وزرو والا مخلوق په څلورو واړو طرفونو حرکت کولے شو، چې هر اړخ ته به يې مخ وو نو بغېر د تاوېدو نه به تلے شول. هغوئ به بغېر د تاوېدو را تاوېدو نه هغه اړخ ته تلل کوم خوا به يې چې مخ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19530, 'Ezekiel 10:12', 'Ezekiel', 10, 12, '&nbsp;د هغوئ ټول بدن، د هغوئ د شاګانو په شمول، د هغوئ لاسونه او د هغوئ وزرونه په مکمل توګه د سترګو نه ډک وُو، لکه څنګه چې د هغوئ څلور پايې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19531, 'Ezekiel 10:13', 'Ezekiel', 10, 13, '&nbsp;ما واورېدل چې پايو ته يې د ”چورلېدونکو پايو“ نامه ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19532, 'Ezekiel 10:14', 'Ezekiel', 10, 14, '&nbsp;د هر يو وزرو والا مخلوق څلور مخونه وُو، اول مخ لکه د غوائى په شان وو، او دوېم مخ يې د انسان په شان وو، درېم مخ يې لکه د ازمرى په شان وو، او څلورم مخ لکه د باز په شان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19533, 'Ezekiel 10:15', 'Ezekiel', 10, 15, '&nbsp;نو بيا دا وزرو والا مخلوق مخ په بره اوچت شو. دا هغه ژوندے مخلوق وو کوم چې ما د کبار د سيند په غاړه ليدلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19534, 'Ezekiel 10:16', 'Ezekiel', 10, 16, '&nbsp;کله چې به دې مخلوق حرکت کولو نو د هغوئ په خوا کښې پايو به هم ورسره حرکت کولو او کله چې به دې مخلوق خپلې وزرې خورې کړې چې د زمکې نه والوځى، نو پايو د هغوئ خوا نۀ پرېښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19535, 'Ezekiel 10:17', 'Ezekiel', 10, 17, '&nbsp;هرکله چې به د وزرو والا مخلوق په آرام ودرېدل، نو پايې به هم ورسره ودرېدې، او کله چې به د وزرو والا مخلوق والوتلو نو پايې به هم ورسره والوتلې، ځکه چې د وزرو والا مخلوق روح په هغې کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19536, 'Ezekiel 10:18', 'Ezekiel', 10, 18, '&nbsp;نو بيا د مالِک خُدائ جلال د خُدائ د کور درشل نه لاړو او د وزرو والا مخلوق دپاسه ودرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19537, 'Ezekiel 10:19', 'Ezekiel', 10, 19, '&nbsp;نو کله چې ما وکتل نو هغه مخلوق خپل وزرونه خوارۀ کړل او د زمکې نه اوچت شول، نو کله چې دوئ لاړل، هغه پايې د هغوئ سره لاړې. هغوئ د خُدائ د کور په درشل کښې نمرخاتۀ طرف ته ودرېدل، او د بنى اِسرائيلو د مالِک خُدائ جلال د هغوئ د سر دپاسه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19538, 'Ezekiel 10:20', 'Ezekiel', 10, 20, '&nbsp;دا هغه ژوندے مخلوق وو کوم چې ما د بنى اِسرائيلو د خُدائ پاک د تخت د لاندې د کبار د سيند په غاړه ليدلے وو، نو زۀ په دې پوهه شوم چې دا هم هغه شان ژوندے مخلوق دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19539, 'Ezekiel 10:21', 'Ezekiel', 10, 21, '&nbsp;د هر يو څلور مخونه او څلور وزرونه وُو، او داسې يو څيز يې د وزرو لاندې وو چې په ليدلو کښې لکه د انسان د لاسونو په شان ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
