(19548, 'Ezekiel 11:8', 'Ezekiel', 11, 8, '&nbsp;تاسو د تُورې نه يرېږئ، او هم دا تُوره به زۀ په تاسو باندې ستاسو خلاف نازله کړم، دا د مالِک قادر مطلق خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19549, 'Ezekiel 11:9', 'Ezekiel', 11, 9, '&nbsp;زۀ به تاسو د ښار نه وشړم او پردو خلقو ته به مو حواله کړم او تاسو له به سزا درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
